#define main wang_program_main
#include "../src/wang_planner.cpp"
#undef main
int main(){Trajectory ref;ref.durations={2.};Curve c=Curve::Zero();c.row(0)<<1.,2.,3.;c.row(1)<<2.,-.4,1.;c.row(2)<<.2,.1,-.3;c.row(3)<<.03,-.07,.04;c.row(7)<<.01,.03,-.02;ref.coefficients={c};Eigen::Matrix<double,3,4> h,t;h<<1,2,.3,-.1, 3,-1,.4,.2, 2,.2,-.5,.1;t<<5,1,-.3,.2, -2,2,.2,-.1, 4,.5,.1,.3;double error=0.;for(double T:{.3,1.,3.}){double a=.2,b=1.7;Curve corr=boundary_correction(ref,a,b,T,h,t);for(int d=0;d<4;++d)for(int end=0;end<2;++end){Vector delta=Vector::Zero();for(int k=d;k<8;++k){double f=1;for(int j=0;j<d;++j)f*=k-j;delta+=corr.row(k).transpose()*f*std::pow(double(end),k-d)/std::pow(T,d);}Vector actual=ref.sample(end?b:a,d)*std::pow((b-a)/T,d)+delta;Vector expected=end?t.col(d):h.col(d);error=std::max(error,(actual-expected).norm());}}std::cout<<Json{{"passed",error<1e-8},{"maximum_endpoint_PVAJ_error",error},{"durations",{.3,1.,3.}}}.dump(2)<<'\n';return error<1e-8?0:1;}
